import { createWorkflowChain } from '@voltagent/core';
import { z } from 'zod';

const workflow = createWorkflowChain({
  id: 'math-workflow',
  name: 'Math Workflow',
  input: z.object({
    value: z.number(),
    operation: z.string()
  }),
  result: z.object({
    result: z.number().optional()
  })
})
.andWhen({
  id: 'double-operation',
  condition: async ({ data }) => data.operation === 'double',
  execute: async ({ data }) => {
    return { ...data, result: data.value * 2 };
  }
})
.andWhen({
  id: 'square-operation',
  condition: async ({ data }) => data.operation === 'square',
  execute: async ({ data }) => {
